"use client";

import {
  autoUpdate,
  computePosition,
  flip,
  offset as floatingOffset,
  shift,
  type Placement,
  type Strategy,
} from "@floating-ui/dom";
import { useEffect, useState, type CSSProperties, type RefObject } from "react";

type UseFloatingPositionOptions<
  TReference extends HTMLElement,
  TFloating extends HTMLElement,
> = {
  floatingRef: RefObject<TFloating | null>;
  matchReferenceWidth?: boolean;
  offset?: number;
  open: boolean;
  padding?: number;
  placement?: Placement;
  referenceRef: RefObject<TReference | null>;
  strategy?: Strategy;
};

function hiddenStyle(strategy: Strategy): CSSProperties {
  return {
    left: 0,
    opacity: 0,
    pointerEvents: "none",
    position: strategy,
    top: 0,
  };
}

export function useFloatingPosition<
  TReference extends HTMLElement = HTMLElement,
  TFloating extends HTMLElement = HTMLElement,
>({
  floatingRef,
  matchReferenceWidth = false,
  offset = 8,
  open,
  padding = 12,
  placement = "bottom-start",
  referenceRef,
  strategy = "fixed",
}: UseFloatingPositionOptions<TReference, TFloating>) {
  const [style, setStyle] = useState<CSSProperties>(() =>
    hiddenStyle(strategy),
  );

  useEffect(() => {
    if (!open) {
      setStyle(hiddenStyle(strategy));
      return;
    }

    const reference = referenceRef.current;
    const floating = floatingRef.current;

    if (!reference || !floating) {
      return;
    }

    let active = true;

    const updatePosition = () => {
      const referenceWidth = matchReferenceWidth
        ? reference.getBoundingClientRect().width
        : undefined;

      void computePosition(reference, floating, {
        middleware: [
          floatingOffset(offset),
          flip({ padding }),
          shift({ padding }),
        ],
        placement,
        strategy,
      }).then(({ x, y }) => {
        if (!active) {
          return;
        }

        setStyle({
          left: x,
          opacity: 1,
          position: strategy,
          top: y,
          width: referenceWidth,
        });
      });
    };

    const cleanup = autoUpdate(reference, floating, updatePosition, {
      elementResize: typeof ResizeObserver !== "undefined",
      layoutShift: typeof IntersectionObserver !== "undefined",
    });

    return () => {
      active = false;
      cleanup();
    };
  }, [
    floatingRef,
    matchReferenceWidth,
    offset,
    open,
    padding,
    placement,
    referenceRef,
    strategy,
  ]);

  return style;
}

const focusableSelector = [
  "a[href]",
  "button:not([disabled])",
  "textarea:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  "[tabindex]:not([tabindex='-1'])",
].join(",");

export function getFocusableElements(container: HTMLElement) {
  return Array.from(container.querySelectorAll<HTMLElement>(focusableSelector))
    .filter((element) =>
      element.tabIndex >= 0 &&
      !element.matches(":disabled, input[type=hidden]") &&
      !element.closest("[hidden], [inert], [aria-hidden=true]") &&
      getComputedStyle(element).visibility === "visible" &&
      !hasDisplayNoneAncestor(element),
    );
}

function hasDisplayNoneAncestor(element: HTMLElement) {
  for (let ancestor: HTMLElement | null = element; ancestor; ancestor = ancestor.parentElement) {
    if (getComputedStyle(ancestor).display === "none") return true;
  }
  return false;
}

export function focusInitialElement(container: HTMLElement) {
  const firstFocusable = getFocusableElements(container)[0] ?? container;
  firstFocusable.focus();
}

export function trapFocus(
  container: HTMLElement,
  event: KeyboardEvent,
  portals: HTMLElement[] = [],
) {
  if (event.key !== "Tab") {
    return;
  }

  const focusableElements = [...new Set([container, ...portals].flatMap(getFocusableElements))];

  if (focusableElements.length === 0) {
    event.preventDefault();
    container.focus();
    return;
  }

  const firstElement = focusableElements[0];
  const lastElement = focusableElements[focusableElements.length - 1];
  const activeElement = document.activeElement;
  const currentIndex = focusableElements.findIndex((element) => element === activeElement);

  if (portals.length && currentIndex >= 0) {
    const offset = event.shiftKey ? -1 : 1;
    event.preventDefault();
    focusableElements[(currentIndex + offset + focusableElements.length) % focusableElements.length].focus();
    return;
  }

  const focusOutsideSequence = currentIndex < 0;

  if (event.shiftKey && (activeElement === firstElement || focusOutsideSequence)) {
    event.preventDefault();
    lastElement.focus();
    return;
  }

  if (!event.shiftKey && (activeElement === lastElement || focusOutsideSequence)) {
    event.preventDefault();
    firstElement.focus();
  }
}

import {
  Children,
  Fragment,
  cloneElement,
  forwardRef,
  isValidElement,
  useMemo,
  version,
  type CSSProperties,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import clsx, { type ClassValue } from "clsx";

// create the swirski tone system
export type SwirskiTone =
  | "muted"
  | "subtle"
  | "inverted"
  | "blue"
  | "yellow"
  | "red"
  | "white"
  | "black";

// create the swirski size system
export type SwirskiSize = "xs" | "sm" | "md" | "lg" | "xl" | "display";

// create the swirski variant system
export type SwirskiVariant = "solid" | "outline" | "soft" | "ghost" | "plain";

export type SwirskiSystemProps<
  Variant extends string = SwirskiVariant,
  Size extends string = SwirskiSize,
  Tone extends string = SwirskiTone,
> = {
  className?: string;
  variant?: Variant;
  size?: Size;
  tone?: Tone;
};

export type SwirskiPolymorphicProps = {
  asChild?: boolean;
  children?: ReactNode;
};
// combines class names
export function cn(...inputs: ClassValue[]) {
  return clsx(...inputs);
}

export const focusVisibleStyles =
  "focus-visible:outline focus-visible:outline-[length:var(--sw-border-width)] focus-visible:outline-offset-2 focus-visible:outline-[var(--sw-color-focus)] forced-colors:focus-visible:outline-solid";

export const disabledInteractiveStyles =
  "disabled:cursor-not-allowed disabled:opacity-60 disabled:hover:translate-x-0 disabled:hover:translate-y-0 disabled:active:translate-x-0 disabled:active:translate-y-0 disabled:active:scale-100";

// apply swirski data attributes to component
export function swirskiAttrs(
  component: string,
  options: {
    size?: string;
    tone?: string;
    variant?: string;
  } = {},
) {
  return {
    "data-swirski-component": component,
    "data-swirski-size": options.size,
    "data-swirski-tone": options.tone,
    "data-swirski-variant": options.variant,
  };
}
// compose the refs so that refs and passed refs will work together
const supportsRefCleanup = Number.parseInt(version, 10) >= 19;

export function composeRefs<T>(...refs: Array<Ref<T> | undefined>) {
  let legacyCleanup: (() => void) | undefined;
  return (node: T | null) => {
    if (node === null && legacyCleanup) {
      const cleanup = legacyCleanup;
      legacyCleanup = undefined;
      cleanup();
      return;
    }

    const cleanups = refs.map((ref) => {
      if (typeof ref === "function") return ref(node);
      if (ref) ref.current = node;
    });

    if (node !== null && cleanups.some((cleanup) => typeof cleanup === "function")) {
      const cleanupRefs = () => {
        refs.forEach((ref, index) => {
          const cleanup = cleanups[index];
          if (typeof cleanup === "function") cleanup();
          else if (typeof ref === "function") ref(null);
          else if (ref) ref.current = null;
        });
      };
      if (supportsRefCleanup) return cleanupRefs;
      // React 18 detaches with null and warns if the callback returns a cleanup.
      legacyCleanup = cleanupRefs;
    }
  };
}

function isEventHandler(key: string, value: unknown) {
  return /^on[A-Z]/.test(key) && typeof value === "function";
}

function mergeSlotProps(
  slotProps: HTMLAttributes<HTMLElement>,
  childProps: HTMLAttributes<HTMLElement>,
) {
  const mergedProps = { ...slotProps, ...childProps };

  for (const key of Object.keys(childProps)) {
    const slotValue = slotProps[key as keyof HTMLAttributes<HTMLElement>];
    const childValue = childProps[key as keyof HTMLAttributes<HTMLElement>];

    if (isEventHandler(key, slotValue) && isEventHandler(key, childValue)) {
      mergedProps[key as keyof HTMLAttributes<HTMLElement>] = ((
        event: unknown,
      ) => {
        (childValue as (event: unknown) => void)(event);
        if (!(event as { defaultPrevented?: boolean } | undefined)?.defaultPrevented) {
          (slotValue as (event: unknown) => void)(event);
        }
      }) as never;
    }
  }

  return {
    ...mergedProps,
    "aria-describedby": mergeAriaIds(
      childProps["aria-describedby"],
      slotProps["aria-describedby"],
    ),
    className: cn(slotProps.className, childProps.className),
    style: {
      ...(slotProps.style as CSSProperties | undefined),
      ...(childProps.style as CSSProperties | undefined),
    },
  };
}

function mergeAriaIds(...values: Array<string | undefined>) {
  const ids = values.flatMap((value) => value?.split(/\s+/) ?? []);
  const uniqueIds = Array.from(new Set(ids.filter(Boolean)));

  return uniqueIds.length ? uniqueIds.join(" ") : undefined;
}

export type SlotProps = HTMLAttributes<HTMLElement> & {
  children?: ReactNode;
};

export const Slot = forwardRef<HTMLElement, SlotProps>(
  ({ children, ...props }, forwardedRef) => {
    const child = Children.only(children);

    if (!isValidElement(child) || child.type === Fragment) {
      throw new Error("Swirski asChild expects one element that can receive DOM props and a ref.");
    }

    const childElement = child as ReactElement<HTMLAttributes<HTMLElement>>;
    const childRef = supportsRefCleanup
      ? (childElement.props as { ref?: Ref<HTMLElement> }).ref
      : (childElement as ReactElement & { ref?: Ref<HTMLElement> }).ref;
    const ref = useMemo(() => composeRefs(forwardedRef, childRef), [forwardedRef, childRef]);

    return cloneElement(childElement, {
      ...mergeSlotProps(props, childElement.props),
      ref,
    } as HTMLAttributes<HTMLElement> & { ref: Ref<HTMLElement> });
  },
);

Slot.displayName = "Slot";

"use client";

import { createContext, useContext, useEffect, useLayoutEffect, useRef, type RefObject } from "react";
import { focusInitialElement, trapFocus as trapFocusWithin } from "./focus";

const useBrowserLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

type LayerOptions = {
  open: boolean;
  contentRef: RefObject<HTMLElement | null>;
  rootRef?: RefObject<HTMLElement | null>;
  onEscape: () => void;
  onOutside?: (event: PointerEvent) => void;
  modal?: boolean;
};

export const OverlayParentContext = createContext<RefObject<HTMLElement | null> | null>(null);
const layers: Array<LayerOptions & { parent: RefObject<HTMLElement | null> | null }> = [];
const hiddenBackground = new Set<Element>();

function getTopModalIndex() {
  return layers.map((entry) => entry.modal).lastIndexOf(true);
}

function updateBackground() {
  for (const element of hiddenBackground) element.removeAttribute("inert");
  hiddenBackground.clear();

  const modalIndex = getTopModalIndex();
  const modal = layers[modalIndex]?.contentRef.current;
  if (!modal) return;
  const modalWrapper = modal.parentElement;

  const allowed = [modal, ...layers.slice(modalIndex + 1).flatMap((entry) =>
    [entry.contentRef.current, entry.rootRef?.current].filter(Boolean),
  )];
  function visit(parent: Element) {
    for (const child of parent.children) {
      if (allowed.includes(child as HTMLElement) ||
          (parent === modalWrapper && child.hasAttribute("data-swirski-backdrop"))) continue;
      if (allowed.some((element) => element && child.contains(element))) {
        visit(child);
      } else if (!child.hasAttribute("inert")) {
        child.setAttribute("inert", "");
        hiddenBackground.add(child);
      }
    }
  }

  visit(modal.ownerDocument.body);
}

export function useOverlayLayer(options: LayerOptions) {
  const parent = useContext(OverlayParentContext);
  const latest = useRef(options);
  useEffect(() => {
    latest.current = options;
  }, [options]);
  const { open, contentRef, rootRef, modal } = options;

  useEffect(() => {
    if (!open) return;

    const layer = { ...latest.current, contentRef, rootRef, modal, parent };
    // A child initially open in the same commit registers before its parent.
    const childIndex = layers.findIndex((entry) =>
      entry.parent === contentRef ||
      contentRef.current?.contains(entry.rootRef?.current ?? entry.contentRef.current),
    );
    layers.splice(childIndex < 0 ? layers.length : childIndex, 0, layer);
    updateBackground();

    const isTop = () => layers[layers.length - 1] === layer;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || event.defaultPrevented || !isTop()) return;
      event.preventDefault();
      latest.current.onEscape();
    };
    const onPointerDown = (event: PointerEvent) => {
      if (!isTop() || event.defaultPrevented) return;
      const path = event.composedPath();
      if (path.some((element) => element === rootRef?.current || element === contentRef.current)) return;
      latest.current.onOutside?.(event);
    };
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("pointerdown", onPointerDown);
    return () => {
      layers.splice(layers.indexOf(layer), 1);
      updateBackground();
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("pointerdown", onPointerDown);
    };
  }, [open, contentRef, rootRef, modal, parent]);
}

let bodyScrollLockCount = 0;
let originalBodyOverflow = "";

function lockBodyScroll() {
  if (bodyScrollLockCount === 0) {
    originalBodyOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
  }

  bodyScrollLockCount += 1;

  return () => {
    bodyScrollLockCount = Math.max(0, bodyScrollLockCount - 1);

    if (bodyScrollLockCount === 0) {
      document.body.style.overflow = originalBodyOverflow;
      originalBodyOverflow = "";
    }
  };
}

export type UseModalOverlayOptions = {
  autoFocus?: boolean;
  contentRef: RefObject<HTMLElement | null>;
  lockScroll?: boolean;
  onEscape: () => void;
  open: boolean;
  restoreFocus?: boolean;
  trapFocus?: boolean;
};

export function useModalOverlay({
  autoFocus = true,
  contentRef,
  lockScroll = true,
  onEscape,
  open,
  restoreFocus = true,
  trapFocus = true,
}: UseModalOverlayOptions) {
  const previousFocus = useRef<HTMLElement | null>(null);
  useBrowserLayoutEffect(() => {
    if (open) previousFocus.current = document.activeElement as HTMLElement | null;
  }, [open]);

  useOverlayLayer({
    open, contentRef, onEscape, modal: true,
    onOutside: (event) => {
      if (event.button === 0 && (event.target as Element)?.parentElement === contentRef.current?.parentElement &&
          (event.target as Element)?.hasAttribute?.("data-swirski-backdrop")) onEscape();
    },
  });

  useEffect(() => {
    if (!open) {
      return;
    }

    const previouslyFocusedElement = previousFocus.current;
    const releaseScrollLock = lockScroll ? lockBodyScroll() : undefined;
    const animationFrame = autoFocus
      ? window.requestAnimationFrame(() => {
          if (contentRef.current &&
              isActiveModal() &&
              !inPortalledLayer(document.activeElement)) {
            focusInitialElement(contentRef.current);
          }
        })
      : undefined;

    const isActiveModal = () =>
      layers[getTopModalIndex()]?.contentRef === contentRef;
    const portalledContent = () => {
      const index = layers.findIndex((layer) => layer.contentRef === contentRef);
      return layers.slice(index + 1).flatMap((layer) => {
        const content = layer.contentRef.current;
        return content && !contentRef.current?.contains(content) ? [content] : [];
      });
    };
    const inPortalledLayer = (target: Node | null) =>
      portalledContent().some((content) => content.contains(target));
    const handleKeyDown = (event: KeyboardEvent) => {
      if (trapFocus && isActiveModal() && !event.defaultPrevented && contentRef.current) {
        trapFocusWithin(contentRef.current, event, portalledContent());
      }
    };
    const handleFocus = (event: FocusEvent) => {
      const target = event.target as Node;
      if (trapFocus && isActiveModal() && contentRef.current &&
          !contentRef.current.contains(target) && !inPortalledLayer(target)) {
        focusInitialElement(contentRef.current);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    document.addEventListener("focusin", handleFocus);
    const observer = new MutationObserver(updateBackground);
    observer.observe(document.body, { childList: true, subtree: true });

    return () => {
      if (animationFrame !== undefined) {
        window.cancelAnimationFrame(animationFrame);
      }

      releaseScrollLock?.();
      window.removeEventListener("keydown", handleKeyDown);
      document.removeEventListener("focusin", handleFocus);
      observer.disconnect();

      if (!restoreFocus) return;
      const activeModal = layers[getTopModalIndex()]?.contentRef.current;
      if (
        previouslyFocusedElement &&
        document.contains(previouslyFocusedElement) &&
        !previouslyFocusedElement.closest("[inert]") &&
        (!activeModal || previouslyFocusedElement !== document.body)
      ) {
        previouslyFocusedElement.focus();
      } else if (activeModal && !activeModal.contains(document.activeElement)) {
        focusInitialElement(activeModal);
      }
    };
  }, [autoFocus, contentRef, lockScroll, open, restoreFocus, trapFocus]);
}

"use client";

import { CSSProperties, HTMLAttributes, ReactNode, createContext, useContext, useState } from "react";
import clsx from "clsx";
import { PortalRootContext } from "../hooks/use-portal-root/usePortalRoot";

export type SwirskiColorScheme = "light" | "dark";

export type SwirskiThemeTokens = {
  colorInk: string;
  colorPaper: string;
  colorSurface: string;
  colorMuted: string;
  colorBlue: string;
  colorYellow: string;
  colorRed: string;
  colorOnBlue: string;
  colorOnYellow: string;
  colorOnRed: string;
  colorBlueText: string;
  colorYellowText: string;
  colorRedText: string;
  colorWhite: string;
  colorBlack: string;
  colorShadow: string;
  colorFocus: string;
  borderWidth: string;
  shadowSm: string;
  shadowMd: string;
  shadowLg: string;
  fontBody: string;
  fontHeading: string;
  fontDisplay: string;
};

export type SwirskiTheme = Partial<SwirskiThemeTokens> & {
  cssVariables?: Record<string, string>;
};

export type SwirskiProviderProps = {
  children: ReactNode;
  colorScheme?: SwirskiColorScheme;
  theme?: SwirskiTheme;
} & HTMLAttributes<HTMLDivElement>;

const defaultTokens: SwirskiThemeTokens = {
  colorInk: "#0B0B0C",
  colorPaper: "#F5F5F3",
  colorSurface: "#FFFFFF",
  colorMuted: "rgba(11, 11, 12, 0.68)",
  colorBlue: "#0057FF",
  colorYellow: "#FFD400",
  colorRed: "#FF3131",
  colorOnBlue: "#FFFFFF",
  colorOnYellow: "#0B0B0C",
  colorOnRed: "#0B0B0C",
  colorBlueText: "#0046D1",
  colorYellowText: "#735800",
  colorRedText: "#A91C1C",
  colorWhite: "#FFFFFF",
  colorBlack: "#0B0B0C",
  colorShadow: "#0B0B0C",
  colorFocus: "#0057FF",
  borderWidth: "4px",
  shadowSm: "3px 3px 0 var(--sw-color-shadow)",
  shadowMd: "6px 6px 0 var(--sw-color-shadow)",
  shadowLg: "10px 10px 0 var(--sw-color-shadow)",
  fontBody: 'var(--font-inter, "Inter Variable", "Inter", system-ui, sans-serif)',
  fontHeading: 'var(--font-anton, "Anton", Impact, sans-serif)',
  fontDisplay: 'var(--font-bangers, "Bangers", Impact, fantasy)',
};

const darkTokens: Partial<SwirskiThemeTokens> = {
  colorInk: "#F7F7F2",
  colorPaper: "#121212",
  colorSurface: "#1D1D1F",
  colorMuted: "rgba(247, 247, 242, 0.68)",
  colorBlueText: "#82AAFF",
  colorYellowText: "#FFD400",
  colorRedText: "#FF7777",
  colorWhite: "#1D1D1F",
  colorBlack: "#F7F7F2",
  colorShadow: "#FFD400",
  colorFocus: "#FFD400",
};

const tokenVariables: Record<keyof SwirskiThemeTokens, string> = {
  colorInk: "--sw-color-ink",
  colorPaper: "--sw-color-paper",
  colorSurface: "--sw-color-surface",
  colorMuted: "--sw-color-muted",
  colorBlue: "--sw-color-blue",
  colorYellow: "--sw-color-yellow",
  colorRed: "--sw-color-red",
  colorOnBlue: "--sw-color-on-blue",
  colorOnYellow: "--sw-color-on-yellow",
  colorOnRed: "--sw-color-on-red",
  colorBlueText: "--sw-color-blue-text",
  colorYellowText: "--sw-color-yellow-text",
  colorRedText: "--sw-color-red-text",
  colorWhite: "--sw-color-white",
  colorBlack: "--sw-color-black",
  colorShadow: "--sw-color-shadow",
  colorFocus: "--sw-color-focus",
  borderWidth: "--sw-border-width",
  shadowSm: "--sw-shadow-sm",
  shadowMd: "--sw-shadow-md",
  shadowLg: "--sw-shadow-lg",
  fontBody: "--sw-font-body",
  fontHeading: "--sw-font-heading",
  fontDisplay: "--sw-font-display",
};

const SwirskiThemeContext = createContext<SwirskiThemeTokens>(defaultTokens);

export const swirskiDefaultTheme = defaultTokens;
export const swirskiDarkTheme = { ...defaultTokens, ...darkTokens };

function resolveTheme(
  colorScheme: SwirskiColorScheme,
  theme?: SwirskiTheme,
): SwirskiThemeTokens {
  const schemeTokens =
    colorScheme === "dark" ? swirskiDarkTheme : swirskiDefaultTheme;

  return {
    ...schemeTokens,
    ...theme,
  };
}

function themeToStyle(theme: SwirskiThemeTokens, extra?: SwirskiTheme) {
  const style: Record<string, string> = {};

  Object.entries(tokenVariables).forEach(([tokenName, variableName]) => {
    style[variableName] = theme[tokenName as keyof SwirskiThemeTokens];
  });

  Object.entries(extra?.cssVariables ?? {}).forEach(([name, value]) => {
    style[name] = value;
  });

  return style as CSSProperties;
}

export function createSwirskiTheme(theme: SwirskiTheme) {
  return theme;
}

export function SwirskiProvider({
  children,
  className,
  colorScheme = "light",
  style,
  theme,
  ...props
}: SwirskiProviderProps) {
  const resolvedTheme = resolveTheme(colorScheme, theme);
  const [portalRoot, setPortalRoot] = useState<HTMLDivElement | null>(null);

  return (
    <SwirskiThemeContext.Provider value={resolvedTheme}>
      <div
        className={clsx(
          "swirski-provider min-h-full bg-[var(--sw-color-paper)] text-[var(--sw-color-ink)]",
          className,
        )}
        data-swirski-color-scheme={colorScheme}
        style={{ ...themeToStyle(resolvedTheme, theme), ...style }}
        {...props}
      >
        <PortalRootContext.Provider value={portalRoot}>
          {children}
          <div ref={setPortalRoot} style={{ display: "contents" }} />
        </PortalRootContext.Provider>
      </div>
    </SwirskiThemeContext.Provider>
  );
}

export function useSwirskiTheme() {
  return useContext(SwirskiThemeContext);
}

export {
  SwirskiProvider,
  createSwirskiTheme,
  swirskiDarkTheme,
  swirskiDefaultTheme,
  useSwirskiTheme,
} from "./SwirskiProvider";
export type {
  SwirskiColorScheme,
  SwirskiProviderProps,
  SwirskiTheme,
  SwirskiThemeTokens,
} from "./SwirskiProvider";

import type { ReactNode } from "react";

export type ButtonTone = "blue" | "yellow" | "red" | "white" | "black";
export type ButtonVariant = "solid" | "outline" | "ghost";
export type ButtonSize = "sm" | "md" | "lg";

export type SharedButtonProps = {
  children?: ReactNode;
  disabled?: boolean;
  size?: ButtonSize;
  tone?: ButtonTone;
  variant?: ButtonVariant | ButtonTone;
  withShadow?: boolean;
  className?: string;
};

const legacyToneVariants: ButtonTone[] = ["blue", "yellow", "red", "white", "black"];

export function resolveButtonStyleConfig(
  props: Pick<SharedButtonProps, "variant" | "tone">,
) {
  if (props.variant && legacyToneVariants.includes(props.variant as ButtonTone)) {
    return {
      variant: "solid" as ButtonVariant,
      tone: (props.tone ?? props.variant) as ButtonTone,
    };
  }

  return {
    variant: (props.variant ?? "solid") as ButtonVariant,
    tone: props.tone ?? "blue",
  };
}

