@source not "./**/*.test.tsx";

@layer utilities {
  @scope (:is([data-swirski-component], :has(> [data-swirski-backdrop])):not([data-swirski-unscoped], [data-swirski-unscoped] *)) to ([data-swirski-unscoped]) {
    @tailwind utilities source(none);
  }
}

@layer base {
  :where([data-swirski-component], [data-swirski-component] *, :has(> [data-swirski-backdrop]), [data-swirski-backdrop]):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    box-sizing: border-box;
    border: 0 solid;
  }

  :where(button, input, select, textarea):where([data-swirski-component]):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    font: inherit;
    color: inherit;
    background-color: transparent;
    padding: 0;
  }

  :where(:is(h1, h2, h3, h4, h5, h6, p, ol, ul)[data-swirski-component]):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    margin: 0;
  }

  :where(a[data-swirski-component]):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    color: inherit;
    text-decoration: none;
  }
}

:root,
[data-swirski-color-scheme="light"] {
  --sw-color-ink: #0b0b0c;
  --sw-color-paper: #f5f5f3;
  --sw-color-surface: #ffffff;
  --sw-color-muted: rgba(11, 11, 12, 0.68);
  --sw-color-blue: #0057ff;
  --sw-color-yellow: #ffd400;
  --sw-color-red: #ff3131;
  --sw-color-on-blue: #ffffff;
  --sw-color-on-yellow: #0b0b0c;
  --sw-color-on-red: #0b0b0c;
  --sw-color-blue-text: #0046d1;
  --sw-color-yellow-text: #735800;
  --sw-color-red-text: #a91c1c;
  --sw-color-white: #ffffff;
  --sw-color-black: #0b0b0c;
  --sw-color-shadow: #0b0b0c;
  --sw-color-focus: #0057ff;
  --sw-border-width: 4px;
  --sw-shadow-sm: 3px 3px 0 var(--sw-color-shadow);
  --sw-shadow-md: 6px 6px 0 var(--sw-color-shadow);
  --sw-shadow-lg: 10px 10px 0 var(--sw-color-shadow);
  --sw-font-body: var(--font-inter, "Inter Variable", "Inter", system-ui, sans-serif);
  --sw-font-heading: var(--font-anton, "Anton", sans-serif);
  --sw-font-display: var(--font-bangers, "Bangers", cursive);
}

[data-swirski-color-scheme="dark"] {
  --sw-color-ink: #f7f7f2;
  --sw-color-paper: #121212;
  --sw-color-surface: #1d1d1f;
  --sw-color-muted: rgba(247, 247, 242, 0.68);
  --sw-color-blue-text: #82aaff;
  --sw-color-yellow-text: #ffd400;
  --sw-color-red-text: #ff7777;
  --sw-color-white: #1d1d1f;
  --sw-color-black: #f7f7f2;
  --sw-color-shadow: #ffd400;
  --sw-color-focus: #ffd400;
}

.swirski-provider {
  min-height: 100%;
  background: var(--sw-color-paper);
  color: var(--sw-color-ink);
  font-family: var(--sw-font-body);
}

@keyframes swirski-pixel-bounce {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-55%);
  }
}

@keyframes swirski-pixel-bars {
  0%,
  100% {
    transform: scaleY(0.45);
  }

  50% {
    transform: scaleY(1);
  }
}

@keyframes swirski-pixel-flicker {
  0%,
  100% {
    opacity: 1;
    transform: translate(0, 0);
  }

  50% {
    opacity: 0.45;
    transform: translate(1px, -1px);
  }
}

@keyframes swirski-pixel-scan {
  0%,
  100% {
    transform: translateX(-100%);
  }

  50% {
    transform: translateX(100%);
  }
}

/* Target only marked library surfaces and internal parts. */
:root {
  --sw-motion-fast: 150ms;
  --sw-motion-standard: 200ms;
}

:where([data-swirski-reduce-motion], [data-swirski-reduce-motion] *):is(.sw-motion-transition, .sw-motion-shift):where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
  transition: none;
}

:where([data-swirski-reduce-motion], [data-swirski-reduce-motion] *).sw-motion-shift:where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
  translate: none;
  scale: none;
}

:where([data-swirski-reduce-motion], [data-swirski-reduce-motion] *).sw-motion-shift:active:not(:disabled, [aria-disabled="true"]):where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
  filter: brightness(0.94);
}

:where([data-swirski-reduce-motion], [data-swirski-reduce-motion] *).sw-motion-loop:where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
  animation: none;
}

:where([data-swirski-reduce-motion], [data-swirski-reduce-motion] *).sw-motion-loading-label:where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
  position: static;
  width: auto;
  height: auto;
  padding: 0;
  margin: 0;
  margin-inline-start: 0.5em;
  overflow: visible;
  clip: auto;
  white-space: normal;
}

@media (prefers-reduced-motion: reduce) {
  :is(.sw-motion-transition, .sw-motion-shift):where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    transition: none;
  }

  .sw-motion-shift:where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    translate: none;
    scale: none;
  }

  .sw-motion-shift:active:not(:disabled, [aria-disabled="true"]):where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    filter: brightness(0.94);
  }

  .sw-motion-loop:where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    animation: none;
  }

  .sw-motion-loading-label:where([data-swirski-component], [data-swirski-component] *):not(:where([data-swirski-unscoped], [data-swirski-unscoped] *)) {
    position: static;
    width: auto;
    height: auto;
    padding: 0;
    margin: 0;
    margin-inline-start: 0.5em;
    overflow: visible;
    clip: auto;
    white-space: normal;
  }
}
